+      const start = template.indexOf("{{", position);
+      if (start < 0) {
+        tokens.push({ type: "text", value: template.slice(position) });
+        position = template.length;
+        break;
+      }
+      if (start > position) tokens.push({ type: "text", value: template.slice(position, start) });
+      const triple = template.startsWith("{{{", start);
+      const close = template.indexOf(triple ? "}}}" : "}}", start + (triple ? 3 : 2));
+      if (close < 0) throw error(template, start, "Unclosed tag");
+      const raw = template.slice(start + (triple ? 3 : 2), close).trim();
+      position = close + (triple ? 3 : 2);
+
+      if (triple) {
+        if (!raw) throw error(template, start, "Interpolation path is required");
+        tokens.push({ type: "value", path: raw, escaped: false });
+        continue;
+      }
+      if (raw.startsWith("!")) {
+        tokens.push({ type: "comment" });
+      } else if (raw === "else") {
+        if (!until) throw error(template, start, "else outside a block");
+        return { tokens, stoppedBy: "else" };
+      } else if (raw.startsWith("/")) {
+        if (!until) throw error(template, start, `Unexpected close ${raw}`);
+        const kind = raw.slice(1).trim();
+        if (kind !== until) throw error(template, start, `Mismatched close: expected /${until}, got /${kind}`);
+        return { tokens, stoppedBy: "close" };
+      } else if (raw.startsWith("#")) {
+        const [kind, ...parts] = raw.slice(1).trim().split(/\s+/);
+        const path = parts.join(" ");
