+    value = (value as Record<string, unknown>)[part];
+  }
+  return value;
+}
+
+function truthy(value: unknown): boolean {
+  return Boolean(value) && !(Array.isArray(value) && value.length === 0);
+}
+
+function scalar(value: unknown): string {
